/* ===================== BÀI 43 · SPI qua GPIO ===================== */
/* Bài 43 · SPI qua GPIO (AMTS-EMB-001-M11-L03, MC51-043) — sinh bởi tools/author/mcu8051/l43.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR43=[{"label":"Ví dụ: Gửi một byte tới 74HC595","code":"; Ví dụ 1: gửi một byte tới thanh ghi dịch 74HC595\n; SCK = P1.4, MOSI = P1.5, MISO = P1.6, CS = P1.7\n; (giả định nối dây; CS tích cực mức thấp, bit 7 trước)\n        ORG     0000H\n        SJMP    MAIN\n; --- SPI_XFER (mode 0: SCK nghỉ 0, lấy mẫu sườn lên):\n;     gửi A, đồng thời nhận 8 bit từ MISO vào A. Dùng R7. ---\nSPI_XFER:\n        MOV     R7,#8\nSX:     RLC     A                       ; CY = bit gửi; bit nhận dồn lên\n        MOV     P1.5,C                  ; MOSI = bit (SCK đang 0)\n        SETB    P1.4                    ; sườn lên: hai bên lấy mẫu\n        MOV     C,P1.6                  ; đọc MISO\n        CLR     P1.4                    ; sườn xuống: hai bên đổi bit\n        MOV     ACC.0,C                 ; bit nhận vào bit 0 của A\n        DJNZ    R7,SX\n        RET\nMAIN:   CLR     P1.4                    ; sau reset SCK = 1: đưa về 0\n        CLR     P1.7                    ; CS = 0: chọn thiết bị\n        MOV     A,#0A5H                 ; mẫu đèn 1010 0101\n        LCALL   SPI_XFER\n        SETB    P1.7                    ; CS lên: 74HC595 chốt ra 8 chân\n        SJMP    $\n        END\n","note":"Gửi A5H tới 74HC595: 8 xung SCK, rồi CS lên chốt ra 8 LED (Q7…Q0 = 1010 0101). 74HC595 không nối MISO nên A nhận về FFH. 91 chu kỳ máy.","dev":{"spi":{"devs":[{"type":"hc595"}]}},"fosc":12000000},{"label":"Ví dụ: Đọc ô nhận dạng, mode 0","code":"; Ví dụ 2: đọc ô nhận dạng (ô 0) của thiết bị SPI, mode 0\n; SCK = P1.4, MOSI = P1.5, MISO = P1.6, CS = P1.7\n; (giả định nối dây; CS tích cực mức thấp, bit 7 trước)\n        ORG     0000H\n        SJMP    MAIN\n; --- SPI_XFER (mode 0: SCK nghỉ 0, lấy mẫu sườn lên):\n;     gửi A, đồng thời nhận 8 bit từ MISO vào A. Dùng R7. ---\nSPI_XFER:\n        MOV     R7,#8\nSX:     RLC     A                       ; CY = bit gửi; bit nhận dồn lên\n        MOV     P1.5,C                  ; MOSI = bit (SCK đang 0)\n        SETB    P1.4                    ; sườn lên: hai bên lấy mẫu\n        MOV     C,P1.6                  ; đọc MISO\n        CLR     P1.4                    ; sườn xuống: hai bên đổi bit\n        MOV     ACC.0,C                 ; bit nhận vào bit 0 của A\n        DJNZ    R7,SX\n        RET\nMAIN:   CLR     P1.4                    ; SCK nghỉ ở 0\n        CLR     P1.7                    ; chọn thiết bị\n        MOV     A,#80H                  ; lệnh: bit 7 = 1 (đọc), ô 0\n        LCALL   SPI_XFER                ; nhận về byte vô nghĩa\n        CLR     A                       ; byte giả 00H chỉ để tạo xung\n        LCALL   SPI_XFER                ; nhận nội dung ô 0\n        SETB    P1.7                    ; bỏ chọn: kết thúc lệnh\n        MOV     30H,A\n        SJMP    $\n        END\n","note":"Lệnh 80H (đọc ô 0) rồi byte giả 00H. Đoán trước: A sau lần truyền thứ hai = ? (5AH, mã nhận dạng). Giải mã: “80/00 00/5A”. 178 chu kỳ.","dev":{"spi":{"devs":[{"type":"reg","mode":0}]}},"fosc":12000000},{"label":"Ví dụ: Thiết bị mode 3, chương trình mode 3","code":"; Ví dụ 3: đọc ô nhận dạng, thiết bị chạy mode 3\n; SCK = P1.4, MOSI = P1.5, MISO = P1.6, CS = P1.7\n; (giả định nối dây; CS tích cực mức thấp, bit 7 trước)\n        ORG     0000H\n        SJMP    MAIN\n; --- SPI_XFER3 (mode 3: SCK nghỉ 1, lấy mẫu sườn lên) ---\nSPI_XFER3:\n        MOV     R7,#8\nSX3:    CLR     P1.4                    ; sườn xuống: hai bên đổi bit\n        RLC     A\n        MOV     P1.5,C                  ; MOSI = bit\n        SETB    P1.4                    ; sườn lên: hai bên lấy mẫu\n        MOV     C,P1.6                  ; đọc MISO\n        MOV     ACC.0,C\n        DJNZ    R7,SX3\n        RET\nMAIN:   SETB    P1.4                    ; mode 3: SCK nghỉ ở 1\n        CLR     P1.7\n        MOV     A,#80H\n        LCALL   SPI_XFER3\n        CLR     A\n        LCALL   SPI_XFER3\n        SETB    P1.7\n        MOV     30H,A\n        SJMP    $\n        END\n","note":"Thiết bị mode 3: SCK nghỉ ở 1, hàm SPI_XFER3 tạo sườn xuống trước rồi sườn lên. Đọc đúng 5AH. Bảng “Đọc MOSI theo mode”: mode 0 và 3 cùng ra 80 00.","dev":{"spi":{"devs":[{"type":"reg","mode":3}]}},"fosc":12000000},{"label":"Lỗi: Thiết bị mode 3, chương trình mode 0","code":"; Ví dụ 4 (lỗi): thiết bị mode 3, chương trình đọc mode 0\n; SCK = P1.4, MOSI = P1.5, MISO = P1.6, CS = P1.7\n; (giả định nối dây; CS tích cực mức thấp, bit 7 trước)\n        ORG     0000H\n        SJMP    MAIN\n; --- SPI_XFER (mode 0: SCK nghỉ 0, lấy mẫu sườn lên):\n;     gửi A, đồng thời nhận 8 bit từ MISO vào A. Dùng R7. ---\nSPI_XFER:\n        MOV     R7,#8\nSX:     RLC     A                       ; CY = bit gửi; bit nhận dồn lên\n        MOV     P1.5,C                  ; MOSI = bit (SCK đang 0)\n        SETB    P1.4                    ; sườn lên: hai bên lấy mẫu\n        MOV     C,P1.6                  ; đọc MISO\n        CLR     P1.4                    ; sườn xuống: hai bên đổi bit\n        MOV     ACC.0,C                 ; bit nhận vào bit 0 của A\n        DJNZ    R7,SX\n        RET\nMAIN:   CLR     P1.4                    ; SAI: thiết bị chờ SCK nghỉ ở 1\n        CLR     P1.7\n        MOV     A,#80H\n        LCALL   SPI_XFER\n        CLR     A\n        LCALL   SPI_XFER\n        SETB    P1.7\n        MOV     30H,A\n        SJMP    $\n        END\n","note":"Thiết bị mode 3, chương trình mode 0: lệnh vẫn tới đúng nhưng MISO bị đọc chậm một bit: 30H = 2DH thay vì 5AH. Không có lỗi nào được báo.","dev":{"spi":{"devs":[{"type":"reg","mode":3}]}},"fosc":12000000}];
const sim43=makeSim51(document.getElementById("m51-l43"),{id:"s43",presets:PR43,ram:256});
makeEx51(document.getElementById("ex-l43"),"l43",[{"t":"Mode SPI ra ba thông số","d":"<p>Ô <code>30H<\/code> chứa cấu hình của một thiết bị SPI: bit 1…0 là số mode (0–3, mode = 2 × CPOL + CPHA), các bit 7…2 là cờ khác, phải bỏ qua. Viết chương trình ghi: <code>31H<\/code> = mức nghỉ của SCK (CPOL: 00H hoặc 01H); <code>32H = 01H<\/code> nếu thiết bị lấy mẫu MOSI ở <b>sườn lên<\/b> của SCK, <code>00H<\/code> nếu ở sườn xuống; <code>33H = 01H<\/code> nếu master phải đặt bit đầu tiên lên MOSI <b>trước<\/b> sườn SCK đầu tiên (CPHA = 0), ngược lại <code>00H<\/code>. Ô <code>30H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>30H = 03H<\/code> (mode 3) → <code>31H = 01H<\/code>, <code>32H = 01H<\/code>, <code>33H = 00H<\/code>.<\/p>","start":"; 30H: bit 1..0 = mode SPI (bit 7..2 là cờ khác, bỏ qua).\n        ORG     0000H\n        MOV     A,30H\n        ANL     A,#02H\n        RR      A\n        MOV     31H,A                   ; CPOL: đúng\n        MOV     32H,#01H                ; SAI: coi mọi mode lấy mẫu sườn lên\n        MOV     A,30H\n        ANL     A,#01H\n        MOV     33H,A                   ; SAI: ngược nghĩa\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":3,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":3,"0x31":1,"0x32":1,"0x33":0}}},{"setup":{"iram":{"0x30":0,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":0,"0x31":0,"0x32":1,"0x33":1}}},{"setup":{"iram":{"0x30":1,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":1,"0x31":0,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x30":2,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":2,"0x31":1,"0x32":0,"0x33":1}}},{"setup":{"iram":{"0x30":129,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":129,"0x31":0,"0x32":0,"0x33":0}}},{"setup":{"iram":{"0x30":254,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":254,"0x31":1,"0x32":0,"0x33":1}}},{"setup":{"iram":{"0x30":124,"0x31":238,"0x32":238,"0x33":238}},"expect":{"iram":{"0x30":124,"0x31":0,"0x32":1,"0x33":1}}}]},"hints":["Tách mode bằng ANL A,#03H. CPOL là bit 1, CPHA là bit 0.","CPHA = 0: lấy mẫu ở sườn đầu (rời mức nghỉ); CPHA = 1: ở sườn sau (về mức nghỉ). Lập bảng 4 mode: sườn lên đúng khi CPOL = CPHA, tức CPOL XOR CPHA = 0.","Đưa CPOL về cùng vị trí bit với CPHA rồi XOR; kết quả còn phải đảo."],"why":"Datasheet thiết bị SPI thường không ghi “mode 3” mà vẽ giản đồ: SCK nghỉ ở mức nào, dữ liệu được chốt ở sườn nào. Từ hai thông tin đó suy ra CPOL, CPHA rồi viết hàm truyền: mức nghỉ quyết định lệnh khởi tạo SCK, sườn lấy mẫu quyết định thứ tự “đặt MOSI → tạo sườn → đọc MISO” trong vòng 8 bit (ví dụ 2 và 3)."},{"t":"Giải mã một khung SPI từ dãy mẫu","d":"<p>Một máy phân tích logic đã lấy mẫu ba đường SPI và chép vào RAM từ <code>40H<\/code>: mỗi ô là một mẫu, bit 0 = SCK, bit 1 = MOSI, bit 2 = CS (các bit khác bằng 0). Dãy kết thúc bằng ô <code>0FFH<\/code>. Ô <code>30H<\/code> là mode của thiết bị (0–3). Viết chương trình giải mã như thiết bị đó: mẫu đầu tiên chưa tạo sườn; với mỗi mẫu sau, nếu CS của mẫu này bằng 0 và SCK đổi so với mẫu trước theo đúng <b>sườn lấy mẫu<\/b> của mode (sườn lên ở mode 0 và 3, sườn xuống ở mode 1 và 2) thì lấy bit MOSI của mẫu này. Kết quả: <code>31H<\/code> = số bit đã lấy; <code>32H<\/code> = byte ghép từ các bit theo thứ tự (bit đầu tiên ở cao nhất, mỗi bit mới dồn vào bit 0; bắt đầu từ 00H; nếu quá 8 bit thì chỉ giữ 8 bit cuối). Ô <code>30H<\/code> và dãy mẫu giữ nguyên.<\/p><p>Ví dụ: master mode 0 gửi A5H (27 mẫu: 06 02 02 03 02 00 01 00 02 03 … 02 06), <code>30H = 00H<\/code> → <code>31H = 08H<\/code>, <code>32H = A5H<\/code>.<\/p>","start":"; 30H = mode của thiết bị (0..3). Mẫu từ 40H: bit 0 = SCK,\n; bit 1 = MOSI, bit 2 = CS; ô 0FFH = hết dãy.\n; Code mẫu: luôn lấy mẫu ở sườn LÊN, chưa xét mode.\n        ORG     0000H\n        MOV     31H,#0\n        MOV     32H,#0\n        MOV     R0,#40H\n        MOV     A,@R0\n        MOV     R2,A                    ; mẫu trước\nLAP:    INC     R0\n        MOV     A,@R0\n        CJNE    A,#0FFH,K1\n        SJMP    XONG\nK1:     MOV     R3,A                    ; mẫu nay\n        JB      ACC.2,TIEP              ; CS = 1: không phải với ta\n        XRL     A,R2\n        JNB     ACC.0,TIEP              ; SCK không đổi\n        MOV     A,R3\n        JNB     ACC.0,TIEP              ; TODO: sườn lấy mẫu theo mode\n        MOV     C,ACC.1                 ; MOSI\n        MOV     A,32H\n        RLC     A\n        MOV     32H,A\n        INC     31H\nTIEP:   MOV     A,R3\n        MOV     R2,A\n        SJMP    LAP\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":6,"0x41":2,"0x42":2,"0x43":3,"0x44":2,"0x45":0,"0x46":1,"0x47":0,"0x48":2,"0x49":3,"0x4A":2,"0x4B":0,"0x4C":1,"0x4D":0,"0x4E":0,"0x4F":1,"0x50":0,"0x51":2,"0x52":3,"0x53":2,"0x54":0,"0x55":1,"0x56":0,"0x57":2,"0x58":3,"0x59":2,"0x5A":6,"0x5B":255,"0x30":0,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":8,"0x32":165}}},{"setup":{"iram":{"0x40":7,"0x41":3,"0x42":2,"0x43":0,"0x44":1,"0x45":0,"0x46":0,"0x47":1,"0x48":0,"0x49":2,"0x4A":3,"0x4B":2,"0x4C":2,"0x4D":3,"0x4E":2,"0x4F":2,"0x50":3,"0x51":2,"0x52":2,"0x53":3,"0x54":2,"0x55":0,"0x56":1,"0x57":0,"0x58":0,"0x59":1,"0x5A":5,"0x5B":255,"0x30":3,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":3,"0x31":8,"0x32":60}}},{"setup":{"iram":{"0x40":6,"0x41":2,"0x42":3,"0x43":3,"0x44":2,"0x45":3,"0x46":1,"0x47":0,"0x48":1,"0x49":1,"0x4A":0,"0x4B":1,"0x4C":3,"0x4D":2,"0x4E":3,"0x4F":1,"0x50":0,"0x51":1,"0x52":3,"0x53":2,"0x54":3,"0x55":3,"0x56":2,"0x57":3,"0x58":1,"0x59":0,"0x5A":4,"0x5B":255,"0x30":1,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":1,"0x31":8,"0x32":150}}},{"setup":{"iram":{"0x40":7,"0x41":3,"0x42":1,"0x43":0,"0x44":1,"0x45":3,"0x46":2,"0x47":3,"0x48":1,"0x49":0,"0x4A":1,"0x4B":3,"0x4C":2,"0x4D":3,"0x4E":3,"0x4F":2,"0x50":3,"0x51":1,"0x52":0,"0x53":1,"0x54":3,"0x55":2,"0x56":3,"0x57":1,"0x58":0,"0x59":1,"0x5A":5,"0x5B":255,"0x30":2,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":2,"0x31":8,"0x32":90}}},{"setup":{"iram":{"0x40":6,"0x41":2,"0x42":0,"0x43":1,"0x44":0,"0x45":0,"0x46":1,"0x47":0,"0x48":0,"0x49":1,"0x4A":0,"0x4B":2,"0x4C":3,"0x4D":2,"0x4E":0,"0x4F":1,"0x50":0,"0x51":0,"0x52":1,"0x53":0,"0x54":2,"0x55":3,"0x56":2,"0x57":0,"0x58":1,"0x59":0,"0x5A":0,"0x5B":1,"0x5C":0,"0x5D":0,"0x5E":1,"0x5F":0,"0x60":2,"0x61":3,"0x62":2,"0x63":2,"0x64":3,"0x65":2,"0x66":0,"0x67":1,"0x68":0,"0x69":2,"0x6A":3,"0x6B":2,"0x6C":0,"0x6D":1,"0x6E":0,"0x6F":0,"0x70":1,"0x71":0,"0x72":4,"0x73":255,"0x30":0,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":16,"0x32":52}}},{"setup":{"iram":{"0x40":6,"0x41":7,"0x42":6,"0x43":7,"0x44":6,"0x45":7,"0x46":6,"0x47":2,"0x48":2,"0x49":3,"0x4A":2,"0x4B":2,"0x4C":3,"0x4D":2,"0x4E":0,"0x4F":1,"0x50":0,"0x51":0,"0x52":1,"0x53":0,"0x54":0,"0x55":1,"0x56":0,"0x57":0,"0x58":1,"0x59":0,"0x5A":2,"0x5B":3,"0x5C":2,"0x5D":2,"0x5E":3,"0x5F":2,"0x60":6,"0x61":255,"0x30":0,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":8,"0x32":195}}},{"setup":{"iram":{"0x40":6,"0x41":2,"0x42":3,"0x43":3,"0x44":2,"0x45":3,"0x46":1,"0x47":0,"0x48":1,"0x49":1,"0x4A":0,"0x4B":1,"0x4C":3,"0x4D":2,"0x4E":3,"0x4F":1,"0x50":0,"0x51":1,"0x52":3,"0x53":2,"0x54":3,"0x55":3,"0x56":2,"0x57":3,"0x58":1,"0x59":0,"0x5A":4,"0x5B":255,"0x30":0,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":0,"0x31":8,"0x32":203}}},{"setup":{"iram":{"0x40":6,"0x41":255,"0x30":2,"0x31":238,"0x32":238}},"expect":{"iram":{"0x30":2,"0x31":0,"0x32":0}}}]},"hints":["Code mẫu đã có khung: giữ mẫu trước ở R2, mẫu nay ở R3, bỏ qua mẫu có CS = 1, XRL hai mẫu để biết SCK có đổi không. Chỉ còn thiếu chọn sườn theo mode.","Tính trước một lần, ngoài vòng lặp: R5 = mức SCK ngay SAU sườn lấy mẫu (01H cho mode 0, 3; 00H cho mode 1, 2). Trong vòng: SCK đổi và SCK mới bằng R5 thì lấy bit.","R5 = NOT (CPOL XOR CPHA). Có thể tính bằng lệnh bit (MOV C,ACC.1 / ANL C,ACC.0 / ORL C,…) hoặc bằng RR A, XRL như bài 1."],"why":"Đây chính là việc máy phân tích SPI trong trình mô phỏng làm khi in bảng “Đọc MOSI theo mode”: cùng một dạng sóng, đọc theo mode khác cho byte khác (bộ thử 7: sóng mode 1 đọc theo mode 0 ra CBH thay vì 96H — lệch một bit). Khi gỡ lỗi SPI trên bo thật, đặt đúng mode cho máy phân tích trước, rồi mới kết luận thiết bị hay chương trình sai."},{"t":"Đảo thứ tự bit, không quá 30 chu kỳ","d":"<p>Cổng nối tiếp của 8051 ở chế độ 0 dịch dữ liệu ra theo thứ tự <b>bit thấp trước<\/b>, còn đa số thiết bị SPI cần <b>bit cao trước<\/b>. Muốn dùng cổng nối tiếp làm “SPI phần cứng” cho thiết bị như vậy, byte phải được đảo thứ tự bit trước khi gửi. Viết chương trình ghi vào <code>31H<\/code> byte <code>30H<\/code> đã đảo thứ tự bit (bit 0 thành bit 7, bit 1 thành bit 6, …). Ô <code>30H<\/code> giữ nguyên. Chạy không quá <b>30 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>), mã không quá <b>40 byte<\/b>. Code mẫu đúng nhưng mất 54 chu kỳ.<\/p><p>Ví dụ: <code>30H = C1H<\/code> (1100 0001B) → <code>31H = 83H<\/code> (1000 0011B).<\/p>","start":"; 31H = byte 30H đảo thứ tự bit (bit 0 thành bit 7...).\n; Đúng nhưng chậm: 54 chu kỳ máy.\n        ORG     0000H\n        MOV     A,30H\n        MOV     R7,#8\nLAP:    RLC     A                       ; CY = bit cao nhất còn lại\n        XCH     A,R6\n        RRC     A                       ; đưa CY vào bit 7 của R6\n        XCH     A,R6\n        DJNZ    R7,LAP\n        MOV     31H,R6\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":193,"0x31":238}},"expect":{"iram":{"0x30":193,"0x31":131}}},{"setup":{"iram":{"0x30":0,"0x31":238}},"expect":{"iram":{"0x30":0,"0x31":0}}},{"setup":{"iram":{"0x30":255,"0x31":238}},"expect":{"iram":{"0x30":255,"0x31":255}}},{"setup":{"iram":{"0x30":1,"0x31":238}},"expect":{"iram":{"0x30":1,"0x31":128}}},{"setup":{"iram":{"0x30":128,"0x31":238}},"expect":{"iram":{"0x30":128,"0x31":1}}},{"setup":{"iram":{"0x30":18,"0x31":238}},"expect":{"iram":{"0x30":18,"0x31":72}}},{"setup":{"iram":{"0x30":107,"0x31":238}},"expect":{"iram":{"0x30":107,"0x31":214}}},{"setup":{"iram":{"0x30":240,"0x31":238}},"expect":{"iram":{"0x30":240,"0x31":15}}}],"maxCyc":30,"maxBytes":40},"hints":["Vòng lặp 8 lần tốn ít nhất 2 chu kỳ cho DJNZ mỗi vòng; trải vòng lặp (viết 8 lần) bỏ được chi phí đó.","A và B đều đánh địa chỉ bit được: MOV C,ACC.0 (1 chu kỳ) rồi MOV B.7,C (2 chu kỳ) chép một bit. 8 cặp = 24 chu kỳ.","Cách khác cũng đạt: bảng 16 byte đảo của nửa byte, tra hai lần bằng MOVC A,@A+DPTR rồi SWAP, ghép bằng ORL."],"why":"Ở 12 MHz mỗi chu kỳ máy là 1 µs: đảo bit bằng vòng lặp hết 54 µs, trải vòng còn 29 µs, tra bảng còn khoảng 17 µs (nhưng tốn 16 byte bảng). Đổi byte mã lấy thời gian là lựa chọn thường gặp trong driver bus. Khi chỉ cần đảo thứ tự với SPI bit-bang thì không cần bảng: đổi RLC thành RRC trong hàm truyền là gửi bit thấp trước."}]);

makeQuiz("quiz43","score43",[{"q": "Thiết bị SPI có SCK nghỉ ở mức 1 và lấy mẫu dữ liệu ở sườn lên. Đó là mode nào?", "o": ["Mode 0", "Mode 2", "Mode 1", "Mode 3"], "a": 3, "e": "SCK nghỉ 1 → CPOL = 1. Rời mức nghỉ là sườn xuống (sườn đầu), nên sườn lên là sườn sau → CPHA = 1. Mode = 2 × 1 + 1 = 3."}, {"q": "Hàm SPI_XFER của bài mất 10 chu kỳ máy mỗi bit. Ở thạch anh 11,0592 MHz, tần số SCK khoảng bao nhiêu?", "o": ["Khoảng 1,1 MHz", "Khoảng 110 kHz", "Khoảng 92 kHz", "Khoảng 920 kHz"], "a": 2, "e": "Một chu kỳ máy = 12 / 11,0592 MHz ≈ 1,085 µs; mỗi bit 10 chu kỳ ≈ 10,85 µs → SCK ≈ 92,2 kHz."}, {"q": "Master muốn ĐỌC một byte từ thiết bị SPI (sau khi đã gửi lệnh đọc). Master phải làm gì?", "o": ["Chờ thiết bị tự tạo SCK", "Gửi một byte giả (ví dụ 00H) để tạo 8 xung SCK, byte nhận về là dữ liệu", "Kéo CS lên rồi đọc MISO một lần", "Gửi địa chỉ 7 bit với bit R/W = 1"], "a": 1, "e": "Chỉ master tạo SCK; mỗi xung đẩy một bit mỗi chiều. Không có xung thì không có bit nào về. Địa chỉ 7 bit và R/W là của I2C."}, {"q": "Trên bus có thiết bị A (mode 0) và thiết bị B (mode 3). Sau khi nói với A, master cần làm gì trước khi kéo CS của B xuống?", "o": ["Không cần làm gì, mode 0 và 3 giống hệt nhau", "Gửi một byte FFH cho B để B chuyển mode", "Đưa SCK về mức nghỉ 1 khi cả hai CS đều đang ở mức 1", "Kéo CS của A và B xuống cùng lúc"], "a": 2, "e": "Hai mode cùng lấy mẫu ở sườn lên nhưng khác mức nghỉ. Nếu SCK còn 0 lúc chọn B, B thiếu sườn xuống đầu tiên (sườn nó đổi bit) nên MISO lệch một bit như ví dụ 4; còn nếu đưa SCK lên 1 sau khi đã chọn B thì B thấy một sườn lên thừa. Đổi mức nghỉ khi không thiết bị nào được chọn."}, {"q": "Gửi 3 byte tới 74HC595 mà CS (nối RCLK) giữ ở mức 0 suốt, cuối cùng mới đưa lên 1. 8 chân ra hiện byte nào?", "o": ["Byte gửi sau cùng", "Byte gửi đầu tiên", "Tổng ba byte", "Không đổi, vì phải chốt sau mỗi byte"], "a": 0, "e": "Thanh ghi dịch giữ 8 bit gần nhất; hai byte đầu bị đẩy ra ngoài (ra chân nối tầng QH′ nếu có). Sườn lên RCLK chốt nội dung lúc đó: byte cuối. Đây chính là cách nối tầng nhiều 74HC595."}]);

